// SMS send gate. Decides whether one text may go out at the instant `now`.
// Pure: no clock, no storage, no network. Never throws; any doubt holds the text.
//
// Rules (first match wins):
//   invalid-input       user or message is missing or malformed
//   opted-out           user replied STOP (optedOutAt set). Holds ALL kinds.
//   opt-out-unreadable  optedOutAt is set but not a valid timestamp (fail closed)
//   no-consent          marketing only: user.sms.optedIn is not true
//   no-opt-out-language marketing only: text does not tell the reader to reply STOP (CTIA)
//   invalid-now         marketing only: `now` is not a valid Date, so local time is unknown
//   timezone-missing    marketing only: no time zone on the profile
//   timezone-invalid    marketing only: time zone is not a name Intl accepts
//   quiet-hours         marketing only: customer's local time is before 08:00 or at/after 21:00
//                       (47 CFR 64.1200(c)(1))
// Transactional texts skip the consent, footer, time zone and quiet-hours rules.

const QUIET_START_HOUR = 8; // first allowed local hour
const QUIET_END_HOUR = 21; // first blocked local hour in the evening

const hold = (rule) => ({ allowed: false, rule });
const ALLOW = () => ({ allowed: true, rule: '' });

const isObject = (v) => typeof v === 'object' && v !== null;

function localHour(now, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(now);
  const hour = Number(parts.find((p) => p.type === 'hour')?.value);
  return Number.isInteger(hour) ? hour : null;
}

function evaluate({ user, message, now }) {
  if (!isObject(user) || !isObject(message)) return hold('invalid-input');
  if (message.kind !== 'marketing' && message.kind !== 'transactional') return hold('invalid-input');
  if (typeof message.text !== 'string' || message.text.trim() === '') return hold('invalid-input');
  if (!isObject(user.sms)) return hold('invalid-input');

  // A STOP reply withdraws consent for every text, including transactional ones.
  const { optedOutAt, optedIn } = user.sms;
  if (optedOutAt !== null && optedOutAt !== undefined) {
    const t = typeof optedOutAt === 'string' ? Date.parse(optedOutAt) : NaN;
    return hold(Number.isNaN(t) ? 'opt-out-unreadable' : 'opted-out');
  }

  if (message.kind === 'transactional') return ALLOW();

  if (optedIn !== true) return hold('no-consent');
  if (!/\bSTOP\b/i.test(message.text)) return hold('no-opt-out-language');

  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return hold('invalid-now');

  const tz = user.timeZone;
  if (tz === null || tz === undefined || (typeof tz === 'string' && tz.trim() === '')) {
    return hold('timezone-missing');
  }
  if (typeof tz !== 'string' || /^[+-]/.test(tz.trim())) return hold('timezone-invalid');

  let hour;
  try {
    hour = localHour(now, tz.trim());
  } catch {
    return hold('timezone-invalid');
  }
  if (hour === null) return hold('timezone-invalid');
  if (hour < QUIET_START_HOUR || hour >= QUIET_END_HOUR) return hold('quiet-hours');

  return ALLOW();
}

export async function checkSend(input) {
  try {
    return evaluate(isObject(input) ? input : {});
  } catch {
    return hold('invalid-input');
  }
}

import { checkSend } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-d1-1/bot.mjs';
import assert from 'node:assert/strict';

const u = (o = {}) => ({ id: '1', timeZone: 'America/Chicago', sms: { optedIn: true, optedOutAt: null }, ...o });
const mk = { kind: 'marketing', text: 'Sale! Reply STOP to opt out.' };
const tx = { kind: 'transactional', text: 'Your box shipped.' };
const at = (s) => new Date(s);
const r = async (user, message, now) => (await checkSend({ user, message, now })).rule;
const ok = { allowed: true, rule: '' };

// Chicago CDT = UTC-5 in October
assert.deepEqual(await checkSend({ user: u(), message: mk, now: at('2026-10-23T18:00:00Z') }), ok); // 13:00
assert.equal(await r(u(), mk, at('2026-10-23T12:59:59Z')), 'quiet-hours'); // 07:59
assert.deepEqual(await checkSend({ user: u(), message: mk, now: at('2026-10-23T13:00:00Z') }), ok); // 08:00
assert.deepEqual(await checkSend({ user: u(), message: mk, now: at('2026-10-24T01:59:59Z') }), ok); // 20:59
assert.equal(await r(u(), mk, at('2026-10-24T02:00:00Z')), 'quiet-hours'); // 21:00
// UTC noon is 21:00 in Tokyo, 17:30 in Kolkata
assert.equal(await r(u({ timeZone: 'Asia/Tokyo' }), mk, at('2026-10-23T12:00:00Z')), 'quiet-hours');
assert.deepEqual(await checkSend({ user: u({ timeZone: 'Asia/Kolkata' }), message: mk, now: at('2026-10-23T12:00:00Z') }), ok);
// DST: Chicago after fall-back (Nov 1 2026): UTC-6
assert.equal(await r(u(), mk, at('2026-11-02T13:59:00Z')), 'quiet-hours'); // 07:59 CST
assert.deepEqual(await checkSend({ user: u(), message: mk, now: at('2026-11-02T14:00:00Z') }), ok);
// transactional ignores quiet hours / tz / consent
const night = at('2026-10-24T08:00:00Z');
assert.deepEqual(await checkSend({ user: u(), message: tx, now: night }), ok);
assert.deepEqual(await checkSend({ user: u({ timeZone: null, sms: { optedIn: false, optedOutAt: null } }), message: tx, now: night }), ok);
// consent / STOP
assert.equal(await r(u({ sms: { optedIn: false, optedOutAt: null } }), mk, at('2026-10-23T18:00:00Z')), 'no-consent');
assert.equal(await r(u({ sms: { optedIn: true, optedOutAt: '2026-10-01T00:00:00Z' } }), mk, at('2026-10-23T18:00:00Z')), 'opted-out');
assert.equal(await r(u({ sms: { optedIn: true, optedOutAt: '2026-10-01T00:00:00Z' } }), tx, at('2026-10-23T18:00:00Z')), 'opted-out');
assert.equal(await r(u({ sms: { optedIn: true, optedOutAt: 'garbage' } }), tx, at('2026-10-23T18:00:00Z')), 'opt-out-unreadable');
// tz problems
assert.equal(await r(u({ timeZone: null }), mk, at('2026-10-23T18:00:00Z')), 'timezone-missing');
assert.equal(await r(u({ timeZone: 'Mars/Olympus' }), mk, at('2026-10-23T18:00:00Z')), 'timezone-invalid');
assert.equal(await r(u({ timeZone: 5 }), mk, at('2026-10-23T18:00:00Z')), 'timezone-invalid');
// footer
assert.equal(await r(u(), { kind: 'marketing', text: 'Sale!' }, at('2026-10-23T18:00:00Z')), 'no-opt-out-language');
// bad input never throws
for (const bad of [undefined, null, 1, 'x', {}, { user: null }, { user: u(), message: null }, { user: u(), message: { kind: 'x', text: 'a' } },
  { user: u(), message: { kind: 'marketing', text: 5 } }, { user: { sms: null }, message: mk, now: new Date() },
  { user: u(), message: mk, now: new Date('nope') }, { user: u(), message: mk, now: 'x' }]) {
  const res = await checkSend(bad);
  assert.equal(res.allowed, false);
  assert.ok(res.rule);
}
